package net.battlespades.bot;
import java.io.*;
import java.nio.*;
import java.nio.file.*;
import java.util.*;
import java.util.zip.*;
/** Immutable semantic surface regions, clearance, passages and monotonic water-to-shore flow. */
public final class NavigationAtlas {
    public static final int WATER=1,DRY=2,LAYERED=4,MAIN_GROUND=8,SHORE=16,CHOKEPOINT=32,NO_SUPPORT=255;
    public static final int MAX_PAYLOAD=512*512*18,MAX_FILE=MAX_PAYLOAD+65536;
    @FunctionalInterface public interface Columns {long word(int column,int word);}
    public record Context(int supportZ,Integer primarySupportZ,int layerCount,int regionId,int clearance,boolean water,boolean underground,boolean mainGround,boolean shore,boolean chokepoint){}
    public record WaterStep(int nextX,int nextY,int goalX,int goalY,int goalSupportZ,int distance,boolean climbable){}
    public record Stats(int width,int height,int dryColumns,int waterColumns,int reachableWaterColumns,int assistedWaterColumns,int unreachableWaterColumns,int layeredColumns,int regions,int mainRegionColumns,int chokepoints,int maximumWaterDistance){}
    public record Loaded(NavigationAtlas atlas,boolean cacheHit){}
    private final int width,height,waterSupport;private final byte[] primary,layers,flags,clearance;private final int[] regions,waterNext,waterGoal,distance;private int mainRegion,regionCount;
    private NavigationAtlas(int width,int height,int waterSupport){if(width<=0||height<=0||width>512||height>512||waterSupport<2||waterSupport>=240)throw new IllegalArgumentException("Invalid navigation atlas dimensions/water support");this.width=width;this.height=height;this.waterSupport=waterSupport;int size=width*height;primary=new byte[size];Arrays.fill(primary,(byte)255);layers=new byte[size];flags=new byte[size];clearance=new byte[size];regions=new int[size];waterNext=new int[size];waterGoal=new int[size];distance=new int[size];Arrays.fill(waterNext,-1);Arrays.fill(waterGoal,-1);}
    public static NavigationAtlas from(CompactVoxelMap map){return build(512,512,239,map::word);}
    public static NavigationAtlas build(int width,int height,int waterSupport,Columns columns){var atlas=new NavigationAtlas(width,height,waterSupport);for(int col=0;col<atlas.area();col++){int first=255,count=0;for(int z=2;z<240;z++)if(bit(columns,col,z)&&!bit(columns,col,z-1)&&!bit(columns,col,z-2)&&z!=waterSupport){if(first==255)first=z;count++;}if(count>0){atlas.primary[col]=(byte)first;atlas.layers[col]=(byte)Math.min(255,count);atlas.flags[col]=(byte)(DRY|(count>1?LAYERED:0));}else if(bit(columns,col,waterSupport))atlas.flags[col]=WATER;}atlas.buildRegions();atlas.buildClearance();for(int rise:new int[]{1,16,240})atlas.buildWater(rise);return atlas;}
    private static boolean bit(Columns columns,int col,int z){return (columns.word(col,z>>>6)&1L<<(z&63))!=0;}
    public int width(){return width;}public int height(){return height;}public int area(){return width*height;}public int waterSupport(){return waterSupport;}
    public int primary(int index){return primary[index]&255;}public int flags(int index){return flags[index]&255;}public int layerCount(int index){return layers[index]&255;}public int clearance(int index){return clearance[index]&255;}public int region(int index){return regions[index];}public int next(int index){return waterNext[index];}public int goal(int index){return waterGoal[index];}public int distance(int index){return distance[index];}
    private int[] neighbors(int index){int x=index%width,y=index/width;int[] result=new int[4];int n=0;if(x+1<width)result[n++]=index+1;if(x>0)result[n++]=index-1;if(y+1<height)result[n++]=index+width;if(y>0)result[n++]=index-width;return Arrays.copyOf(result,n);}
    private boolean connected(int a,int b){return (flags(a)&DRY)!=0&&(flags(b)&DRY)!=0&&Math.abs(primary(a)-primary(b))<=2;}
    private void buildRegions(){var sizes=new ArrayList<Integer>();sizes.add(0);var queue=new ArrayDeque<Integer>();for(int start=0;start<area();start++){if((flags(start)&DRY)==0||regions[start]!=0)continue;int region=sizes.size(),size=0;queue.add(start);regions[start]=region;while(!queue.isEmpty()){int current=queue.removeFirst();size++;for(int neighbor:neighbors(current))if(regions[neighbor]==0&&connected(current,neighbor)){regions[neighbor]=region;queue.addLast(neighbor);}}sizes.add(size);}regionCount=sizes.size()-1;if(regionCount==0)return;mainRegion=1;for(int region=2;region<sizes.size();region++)if(sizes.get(region)>sizes.get(mainRegion))mainRegion=region;for(int index=0;index<area();index++)if(regions[index]==mainRegion)flags[index]|=MAIN_GROUND;}
    private void buildClearance(){var queue=new ArrayDeque<Integer>();for(int index=0;index<area();index++){int region=regions[index];if(region<=0)continue;boolean boundary=false;int count=0;for(int neighbor:neighbors(index))if(regions[neighbor]==region&&connected(index,neighbor))count++;else boundary=true;int x=index%width,y=index/width;if(x==0||x==width-1||y==0||y==height-1)boundary=true;if(boundary||count<4){clearance[index]=1;queue.addLast(index);}}while(!queue.isEmpty()){int current=queue.removeFirst(),next=Math.min(255,clearance(current)+1),region=regions[current];for(int neighbor:neighbors(current))if(clearance[neighbor]==0&&regions[neighbor]==region&&connected(current,neighbor)){clearance[neighbor]=(byte)next;queue.addLast(neighbor);}}for(int index=0;index<area();index++)if((flags(index)&MAIN_GROUND)!=0){int degree=0;for(int neighbor:neighbors(index))if(connected(index,neighbor)&&regions[neighbor]==regions[index])degree++;if(clearance(index)<=2&&degree<=2)flags[index]|=CHOKEPOINT;}}
    private void buildWater(int maximumRise){var queue=new ArrayDeque<Integer>();for(int index=0;index<area();index++){if((flags(index)&WATER)==0||distance[index]!=0)continue;int best=-1,delta=240;for(int neighbor:neighbors(index)){if((flags(neighbor)&DRY)==0)continue;int x=neighbor%width,y=neighbor/width;if(x==0||x==width-1||y==0||y==height-1)continue;int rise=Math.abs(primary(neighbor)-waterSupport);if(rise<=maximumRise&&rise<delta){best=neighbor;delta=rise;}}if(best<0)continue;waterNext[index]=waterGoal[index]=best;distance[index]=1;flags[best]|=SHORE;queue.addLast(index);}while(!queue.isEmpty()){int current=queue.removeFirst();if(distance[current]>=65535)continue;for(int neighbor:neighbors(current))if((flags(neighbor)&WATER)!=0&&distance[neighbor]==0){waterNext[neighbor]=current;waterGoal[neighbor]=waterGoal[current];distance[neighbor]=distance[current]+1;queue.addLast(neighbor);}}}
    public Context context(int x,int y,int support){if(x<0||x>=width||y<0||y>=height)return null;int index=y*width+x,flag=flags(index),p=primary(index),count=layerCount(index);return new Context(support,p==255?null:p,count,regions[index],clearance(index),(flag&WATER)!=0,count>1&&p!=255&&support>p+1,(flag&MAIN_GROUND)!=0,(flag&SHORE)!=0,(flag&CHOKEPOINT)!=0&&p!=255&&Math.abs(support-p)<=1);}
    public WaterStep waterRoute(int x,int y){if(x<0||x>=width||y<0||y>=height)return null;int index=y*width+x,n=waterNext[index],g=waterGoal[index],d=distance[index];if(d<=0||n<0||g<0||primary(g)==255)return null;return new WaterStep(n%width,n/width,g%width,g/width,primary(g),d,Math.abs(primary(g)-waterSupport)<=1);}
    public Stats stats(){int dry=0,water=0,reachable=0,assisted=0,layered=0,main=0,choke=0,max=0;for(int i=0;i<area();i++){int f=flags(i);if((f&DRY)!=0)dry++;if((f&WATER)!=0){water++;if(distance[i]>0){reachable++;if(Math.abs(primary(waterGoal[i])-waterSupport)>2)assisted++;}}if((f&LAYERED)!=0)layered++;if((f&MAIN_GROUND)!=0)main++;if((f&CHOKEPOINT)!=0)choke++;max=Math.max(max,distance[i]);}return new Stats(width,height,dry,water,reachable,assisted,water-reachable,layered,regionCount,main,choke,max);}
    public void validate(){if(mainRegion<0||mainRegion>regionCount)throw new IllegalArgumentException("Invalid atlas main region");for(int i=0;i<area();i++){int f=flags(i),p=primary(i),r=regions[i],n=waterNext[i],g=waterGoal[i],d=distance[i];if((f&~63)!=0||(f&WATER)!=0&&(f&DRY)!=0||p!=255&&(p<2||p>=240)||r<0||r>regionCount)throw new IllegalArgumentException("Invalid atlas flags/surface/region");if((f&DRY)!=0){if(p==255||r<=0)throw new IllegalArgumentException("Dry column has no region");}else if(r!=0)throw new IllegalArgumentException("Non-dry column owns region");if(d<=0){if(n!=-1||g!=-1)throw new IllegalArgumentException("Unrouted water metadata not empty");continue;}if((f&WATER)==0||n<0||n>=area()||g<0||g>=area()||Math.abs(n%width-i%width)+Math.abs(n/width-i/width)!=1||(flags(g)&DRY)==0)throw new IllegalArgumentException("Invalid water edge/goal");if(d==1){if(n!=g)throw new IllegalArgumentException("Shore edge misses goal");}else if((flags(n)&WATER)==0||distance[n]!=d-1||waterGoal[n]!=g)throw new IllegalArgumentException("Water distance not decreasing");}}
    public static byte[] sourceDigest(byte[] raw){return Blake2s128.digest(raw);}
    public byte[] encode(byte[] digest){if(digest.length!=16)throw new IllegalArgumentException("Atlas digest must be 16 bytes");validate();var raw=ByteBuffer.allocate(area()*18+8).order(ByteOrder.LITTLE_ENDIAN);raw.put(primary).put(layers).put(flags).put(clearance);for(int[] values:List.of(regions,waterNext,waterGoal))for(int value:values)raw.putInt(value);for(int value:distance)raw.putShort((short)value);raw.putInt(mainRegion).putInt(regionCount);var deflater=new Deflater(6);var compressed=new ByteArrayOutputStream();try{deflater.setInput(raw.array());deflater.finish();byte[] buffer=new byte[8192];while(!deflater.finished()){int n=deflater.deflate(buffer);compressed.write(buffer,0,n);}}finally{deflater.end();}byte[] bytes=compressed.toByteArray();return ByteBuffer.allocate(40+bytes.length).order(ByteOrder.LITTLE_ENDIAN).put(new byte[]{'B','S','N','A','V','0','1',0}).putShort((short)2).putShort((short)width).putShort((short)height).putShort((short)waterSupport).put(digest).putInt(raw.capacity()).putInt(bytes.length).put(bytes).array();}
    public static NavigationAtlas decode(byte[] data,byte[] expected){if(data.length<40||data.length>MAX_FILE)throw new IllegalArgumentException("Invalid atlas file size");var header=ByteBuffer.wrap(data).order(ByteOrder.LITTLE_ENDIAN);byte[] magic=new byte[8],digest=new byte[16];header.get(magic);int version=Short.toUnsignedInt(header.getShort()),width=Short.toUnsignedInt(header.getShort()),height=Short.toUnsignedInt(header.getShort()),water=Short.toUnsignedInt(header.getShort());header.get(digest);int rawSize=header.getInt(),compressed=header.getInt();if(!Arrays.equals(magic,new byte[]{'B','S','N','A','V','0','1',0})||version!=2||!Arrays.equals(digest,expected)||compressed!=data.length-40||width<=0||width>512||height<=0||height>512||rawSize!=(long)width*height*18+8||rawSize>MAX_PAYLOAD+8)throw new IllegalArgumentException("Atlas identity/size mismatch");byte[] raw=new byte[rawSize+1];var inflater=new Inflater();try{inflater.setInput(data,40,compressed);int offset=0;while(!inflater.finished()&&offset<raw.length){int n=inflater.inflate(raw,offset,raw.length-offset);offset+=n;if(n==0)break;}if(offset!=rawSize||!inflater.finished()||inflater.getRemaining()!=0)throw new IllegalArgumentException("Invalid decoded atlas length");}catch(DataFormatException invalid){throw new IllegalArgumentException("Corrupt atlas payload",invalid);}finally{inflater.end();}var atlas=new NavigationAtlas(width,height,water);var payload=ByteBuffer.wrap(raw,0,rawSize).order(ByteOrder.LITTLE_ENDIAN);payload.get(atlas.primary).get(atlas.layers).get(atlas.flags).get(atlas.clearance);for(int[] values:List.of(atlas.regions,atlas.waterNext,atlas.waterGoal))for(int i=0;i<values.length;i++)values[i]=payload.getInt();for(int i=0;i<atlas.area();i++)atlas.distance[i]=Short.toUnsignedInt(payload.getShort());atlas.mainRegion=payload.getInt();atlas.regionCount=payload.getInt();atlas.validate();return atlas;}
    public void write(Path destination,byte[] digest)throws IOException{Path path=destination.toAbsolutePath();Files.createDirectories(path.getParent());byte[] bytes=encode(digest);Path temporary=Files.createTempFile(path.getParent(),"."+path.getFileName(),".tmp");try{Files.write(temporary,bytes);try{Files.move(temporary,path,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(AtomicMoveNotSupportedException noAtomic){Files.move(temporary,path,StandardCopyOption.REPLACE_EXISTING);}}finally{Files.deleteIfExists(temporary);}}
    public static Loaded loadOrBuild(CompactVoxelMap map,byte[] raw,Path directory,String name){byte[] digest=sourceDigest(raw);if(directory!=null&&!name.isEmpty()){String stem=Path.of(name).getFileName().toString();if(stem.toLowerCase(Locale.ROOT).endsWith(".vxl"))stem=stem.substring(0,stem.length()-4);Path path=directory.resolve(stem+".botnav");try{if(Files.size(path)<=MAX_FILE){byte[] bytes;try(var in=Files.newInputStream(path)){bytes=in.readNBytes(MAX_FILE+1);}return new Loaded(decode(bytes,digest),true);}}catch(IOException|IllegalArgumentException invalid){/* A cache never replaces the collision map's authority. */}}return new Loaded(from(map),false);}
}
